from __future__ import annotations

import csv
import datetime as dt
import json
import math
import re
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET_DIR = Path("/app/dataset")


def _read_csv(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def _parse_valid_date(value: str) -> dt.date | None:
    try:
        return dt.date.fromisoformat(value)
    except ValueError:
        return None


def _month_starts(first_date: dt.date, last_date: dt.date) -> list[dt.date]:
    """First matching weekday in each calendar month covered by the data."""
    starts: list[dt.date] = []
    weekday = first_date.weekday()
    current = dt.date(first_date.year, first_date.month, 1)

    while current <= last_date:
        start = current + dt.timedelta(days=(weekday - current.weekday()) % 7)
        if first_date <= start <= last_date:
            starts.append(start)

        if current.month == 12:
            current = dt.date(current.year + 1, 1, 1)
        else:
            current = dt.date(current.year, current.month + 1, 1)

    return starts


def _billing_month_index(day: dt.date, starts: list[dt.date]) -> int | None:
    idx = None
    for i, start in enumerate(starts):
        if day >= start:
            idx = i
        else:
            break
    return idx


def _round_salary(value: Decimal) -> int:
    return int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def answer() -> dict[str, list[int]]:
    employees = _read_csv(DATASET_DIR / "employees.csv")
    tasks = _read_csv(DATASET_DIR / "tasks.csv")
    timesheet = _read_csv(DATASET_DIR / "timesheet.csv")

    hourly_rates = {
        row["PESEL"]: Decimal(row["hourly_rate"]) for row in employees
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"]) for row in tasks
    }

    # Remove exact duplicate business rows. The row id is only a record id.
    unique_rows: list[dict[str, str]] = []
    seen: set[tuple[tuple[str, str], ...]] = set()
    for row in timesheet:
        key = tuple((k, v) for k, v in row.items() if k != "id")
        if key in seen:
            continue
        seen.add(key)
        unique_rows.append(row)

    dated_rows: list[tuple[dict[str, str], dt.date]] = []
    valid_dates: list[dt.date] = []
    for row in unique_rows:
        day = _parse_valid_date(row["date"])
        if day is None:
            continue
        valid_dates.append(day)
        if row["employee_id"] in hourly_rates:
            dated_rows.append((row, day))

    if not valid_dates:
        return {row["PESEL"]: [] for row in employees}

    starts = _month_starts(min(valid_dates), max(valid_dates))
    totals: dict[str, list[Decimal]] = {
        row["PESEL"]: [Decimal("0") for _ in starts] for row in employees
    }

    for row, day in dated_rows:
        month_idx = _billing_month_index(day, starts)
        if month_idx is None:
            continue

        pesel = row["employee_id"]
        hours = Decimal(row["hours_worked"])
        base_pay = hours * hourly_rates[pesel]

        task_ids = [int(value) for value in re.findall(r"\d+", row["performed_tasks"])]
        bonus = sum((task_pay[task_id] for task_id in task_ids if task_id in task_pay), Decimal("0"))

        totals[pesel][month_idx] += base_pay + bonus

    return {
        row["PESEL"]: [_round_salary(value) for value in totals[row["PESEL"]]]
        for row in employees
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as f:
        json.dump(answer(), f, default=list)
